function getTrack(id) {
  return tracks[id] || tracks.engineering
}

function getProjectsForTrack(trackId) {
  if (trackId === 'all') {
    return projects
      .slice()
      .sort((a, b) => (a.priority.all || 99) - (b.priority.all || 99))
  }

  return projects
    .filter(project => project.tracks.includes(trackId))
    .slice()
    .sort((a, b) => (a.priority[trackId] || 99) - (b.priority[trackId] || 99))
}

function getProject(slug) {
  return projects.find(project => project.slug === slug)
}

export default {
  tracks,
  projects,
  experience,
  getTrack,
  getProjectsForTrack,
  getProject
}
