import { parse as parseYaml } from 'yaml'

const articleFiles = require.context('@/content/projects', false, /\.md$/)

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;')
}

function inlineMarkdown(value) {
  return escapeHtml(value)
    .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
    .replace(/\[(.+?)\]\((.+?)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>')
}

function markdownToHtml(markdown) {
  return String(markdown || '')
    .trim()
    .split(/\n{2,}/)
    .filter(Boolean)
    .map(block => {
      const text = block.trim()
      if (text.startsWith('- ')) {
        const items = text
          .split('\n')
          .filter(line => line.trim().startsWith('- '))
          .map(line => `<li>${inlineMarkdown(line.replace(/^\s*-\s*/, ''))}</li>`)
          .join('')
        return `<ul>${items}</ul>`
      }
      return `<p>${inlineMarkdown(text.replace(/\n/g, ' '))}</p>`
    })
    .join('')
}

function parseSections(markdown) {
  const sections = []
  const pattern = /^##\s+(.+)$/gm
  const matches = [...String(markdown || '').matchAll(pattern)]

  matches.forEach((match, index) => {
    const next = matches[index + 1]
    const bodyStart = match.index + match[0].length
    const bodyEnd = next ? next.index : markdown.length
    const body = markdown.slice(bodyStart, bodyEnd).trim()

    sections.push({
      title: match[1].trim(),
      body,
      bodyHtml: markdownToHtml(body)
    })
  })

  return sections
}

function parseArticle(raw) {
  const match = String(raw).match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/)
  if (!match) {
    return {
      positioning: '',
      positioningHtml: '',
      sections: parseSections(raw)
    }
  }

  const data = parseYaml(match[1]) || {}
  const body = match[2].trim()

  return {
    ...data,
    positioningHtml: markdownToHtml(data.positioning || ''),
    sections: parseSections(body),
    body
  }
}

const articles = articleFiles.keys().reduce((memo, fileName) => {
  const slug = fileName.replace('./', '').replace(/\.md$/, '')
  memo[slug] = parseArticle(articleFiles(fileName))
  return memo
}, {})

export default articles
